def main():
    if len(sys.argv) < 2 or sys.argv[1] not in CMDS:
        names = ", ".join(sorted(CMDS))
        print(f"usage: python {sys.argv[0]} <command> [args...]")
        print(f"commands: {names}")
        raise SystemExit(2)
    cmd = sys.argv[1]
    sys.argv = [cmd] + sys.argv[2:]
    globs = {"__name__": "__main__", "__file__": cmd + ".py"}
    exec(compile(CMDS[cmd], cmd + ".py", "exec"), globs)

if __name__ == "__main__":
    main()
